    [2201] = "Trova il rubino, lo zaffiro e il topazio sparsi per Uldaman. Una volta ottenuti, contatta Talvash Kissel a distanza usando la Fiala della Divinazione che ti ha dato in precedenza.$B$BDal diario sai che...$B* Il rubino è stato nascosto in un'area Shadowforge barricata.$B* Il topazio è stato nascosto in un'urna in una delle zone dei trogg, vicino ad alcuni nani dell'Alleanza.$B$B* Lo zaffiro è stato preso da Grimlok, il capo dei trogg.",
    [2202] = "Porta 12 Funghi Cappella Magenta a Jarkal Fondimuschio a Kargath.",
    [2204] = "Ottieni una fonte di energia dal costrutto più potente che riesci a trovare a Uldaman e consegnala a Talvash Kissel a Forgiardente.",
    [2240] = "Leggi il Diario di Baelog, esplora la camera nascosta, poi fai rapporto al Prospettore Piccatonante.",
    [2278] = "Parla con il guardiano di pietra e scopri quale sapere antico custodisce. Una volta appreso il sapere che ha da offrire, attiva i Dischi di Norgannon.",
    [2279] = "Porta la versione in miniatura dei Dischi di Norgannon alla Lega degli Esploratori a Forgiardente.",
    [2280] = "Porta la versione in miniatura dei Dischi di Norgannon a uno dei saggi di Picco del Tuono.",
    [2283] = "Cerca una collana di valore nel sito di scavo di Uldaman e portala a Dran Droffers a Orgrimmar. La collana potrebbe essere danneggiata.",
    [2284] = "Trova un indizio su dove si trovino le gemme nelle profondità di Uldaman.",
    [2318] = "Trova qualcuno in grado di tradurre il diario del paladino. Il luogo più vicino in cui potresti trovare qualcuno è Kargath, nelle Maleterre.",
    [2338] = "Presta la collana a Jarkal. In cambio, tradurrà il diario per te.",
    [2339] = "Recupera a Uldaman tutte e tre le gemme e una fonte di energia per la collana, poi portale a Jarkal Fondimuschio a Kargath. Jarkal crede che una fonte di energia si possa trovare sul costrutto più potente di Uldaman.$B$BDal diario sai che...$B* Il rubino è stato nascosto in un'area Shadowforge barricata.$B* Il topazio è stato nascosto in un'urna in una delle zone dei trogg, vicino ad alcuni nani dell'Alleanza.$B* Lo zaffiro è stato preso da Grimlok, il capo dei trogg.",
    [2340] = "Consegna la collana e le gemme recuperate a Dran Droffers a Orgrimmar.",
    [2341] = "Fai visita a Jarkal Fondimuschio a Kargath per scoprire se ci è riuscito.",
    [2342] = "Prendi il tesoro di famiglia di Patrick Garrett dal forziere della sua famiglia nella Sala Comune Sud di Uldaman e portaglielo a Sepulcra.",
    [2359] = "Ruba la Chiave della Torre dei Defias, irrompi nella Torre dei Defias e scopri il contenuto del Forziere di Boscovespro. Porta tutte le informazioni che trovi a Mathias Shaw a Roccavento. Leggi il Diario di Kearnen per saperne di più sulla torre.\\n",
    [2360] = "Recati nelle Marche Occidentali e trova l'Agente Kearnen per il rapporto.",
    [2361] = "Ti dono con piacere questa collana, potente $C. Mi hai reso un servizio inestimabile, e per questo ti ringrazio. Indossala con orgoglio, e assicurati di dire a gran voce, e più volte, chi l'ha creata per te!$B$BE se potessi aggiungere che non è affatto maledetta, sarebbe magnifico.",
    [2398] = "Trova Baelog a Uldaman.",
    [2418] = "Porta 8 Pietre del Potere di Dentrium e 8 Pietre del Potere di An'Alleum a Razzopazzo nelle Maleterre.",
    [2439] = "Porta il tuo buono premio a Dinita Stonemantle nel Caveau di Forgiardente.",
    [2440] = "Porta il buono premio a Bena Winterhoof a Picco del Tuono.",
    [2458] = "Raggiungi la Torre della Ventura & Co., a nord della Palude Fangosa, e contatta l'agente segreto della Mano Infranta, il Coordinatore Fizzule.$B$BQuando la torre è in vista, usa la Pistola Lanciarazzi per segnalare il tuo arrivo al Coordinatore Fizzule. Spara DUE razzi, poi avvicinati al Coordinatore Fizzule ed esegui il saluto infranto (/salute).$B$BQueste azioni vanno eseguite nell'ordine corretto, perché Fizzule attaccherà ed eliminerà chiunque non riconosca.",
    [2460] = "Esegui il saluto infranto davanti a Shenthul.",
    [2478] = "Ruba la Chiave della Torre di Silixiz al Caposghigno Silixiz, poi uccidi due Fuchi Mutati della Ventura & Co., due Pattugliatori della Ventura & Co. e due Vedette della Ventura & Co.$B$BAssassina il Gran Caposghigno Gallywix e prendi la sua testa, poi scassina la cassetta di sicurezza di Gallywix e ruba la Scorta della Miscela Alterata di Zanzil. Porta la Scorta e la Testa di Gallywix a Shenthul a Orgrimmar per ulteriori istruzioni.\\n",
    [2479] = "Recati a Mulino di Tarren, nelle Alture di Colletorto, e consegna il Campione della Miscela di Zanzil a Serge Hinott.$B$BPer raggiungere Mulino di Tarren, prendi lo zeppelin per Sepulcra e segui la strada verso sud attraverso la Selva Pinargento, in direzione di Colletorto. Segui i cartelli!\\n\\n",
    [2480] = "Aspetta che Serge Hinott completi la cura.",
    [2607] = "Parla con il Dottor Tranciasega nella cantina della Caserma.",
    [2608] = "/Sdraiati per farti visitare da Doc Mixilpixil. Come può trovare la cura se non trova la causa?",
    [2609] = "Porta al Dottor Tranciasega un mazzo di Fiori Selvatici Semplici, una Fiala Piombata, un Tubo di Bronzo e un Rocchetto di Filo di Seta Verde Chiaro. La 'ite' non guarisce da sola, $g giovanotto:signorina;.",
    [2621] = "Parla con il Comandante delle Comunicazioni Ruag a Pietrachiusa.",
    [2622] = "Parla con Bengor.",
    [2623] = "Recupera gli Ordini del Capoguerra e riportali all'Eroe dell'Orda Caduto.",
    [2681] = "Libera nove Servitori di Razelikh, tre Servitori di Sevine, tre Servitori di Allistarj e tre Servitori di Grol. Torna dall'Eroe Caduto una volta completato il compito. Devi restare vicino alle pietre, altrimenti il processo fallirà.",
    [2701] = "Apri il forziere e prendi la tua ricompensa.",
    [2702] = "Parla con il Caporale Thund Zoccolo Spezzato.",
    [2721] = "Scopri che fine ha fatto il Tenente Kirith.",
    [2743] = "Torna dall'Eroe dell'Orda Caduto con le tue scoperte.",
    [2744] = "Parla con Loramus Thalipedes ad Azshara.",
    [2745] = "Parla con Tyrion nel Castello di Roccavento.",
    [2746] = "Porta 3 Stoffe di Seta e 2 Mele Fresche di Clara a Tyrion a Roccavento.",
    [2768] = "Porta la Verga Divinomatica al Capo Ingegnere Segachiodi a Meccania.",
    [2770] = "Porta la Scaglia Elettrificata di Gahz'rilla a Wizzle Brassbolts nelle Distese Salate.",
    [2783] = "Parla con l'Eroe dell'Orda Caduto al confine tra le Terre Devastate e la palude.",
    [2784] = "Ascolta l'Eroe dell'Orda Caduto mentre racconta la sua storia.",
    [2801] = "Ascolta l'Eroe dell'Orda Caduto mentre racconta la sua storia.",
    [2846] = "Porta la Tiara del Profondo a Tabetha ad Acquemorte.",
    [2861] = "Parla con Tabetha ad Acquemorte.",
    [2864] = "Parla con Tran'rek a Meccania.",
    [2865] = "Porta 5 Gusci di Scarabeo Intatti a Tran'rek a Meccania.",
    [2936] = "Leggi la Tavoletta di Theka per scoprire il nome del dio ragno degli Scorzasecca, poi torna dal Maestro Gadrin.",
    [2983] = "Trova Kranal Fiss nelle Savane.",
    [2984] = "Trova Kranal Fiss nelle Savane.",
    [2985] = "Trova Islen Scruta Lagune nelle Savane.",
    [2986] = "Trova Islen Scruta Lagune nelle Savane.",
    [2991] = "Porta il Medaglione di Nekrum a Thadius Ombratetra nelle Terre Devastate.",
    [3001] = "Trova Strahad Farsan a Porto Paranco.",
    [3042] = "Porta 20 fiale di Sudore di Troll a Trenton Sveltamano a Meccania.",
    [3141] = "Ascolta Loramus Thalipedes mentre racconta la sua storia.",
    [3369] = "Porta la Scheggia dell'Incubo a Hamuul Totem Runico sull'Altura degli Anziani.",
    [3370] = "Porta la Scheggia dell'Incubo a Mathrengyl Domaorsi a Darnassus.",
    [3373] = "Colloca l'Essenza di Eranikus nella Fonte dell'Essenza che si trova in questa tana, nel Tempio Sommerso.",
    [3380] = "Trova Marvon Cercachiodi a Tanaris.",
    [3446] = "Trova l'Altare di Hakkar nel Tempio Sommerso, nella Palude del Dolore.",
    [3447] = "Addentrati nel Tempio Sommerso e scopri il segreto nascosto nel cerchio di statue.",
    [3504] = "Consegna la Lettera Sigillata per Ag'tor ad Ag'tor Bloodfist, ad Azshara.",
    [3505] = "Uccidi 6 Recuperatori Elfi del Sangue e 6 Topografi Elfi del Sangue, poi trova la fonte del potere di Rimtori.",
    [3508] = "Aspetta che Loramus completi l'incantesimo di illuminazione.",
    [3509] = "Parla con Sire Arkkoroc ad Azshara. Inizia la ricerca in riva al mare per trovare il Tempio di Arkkoran.",
    [3510] = "Uccidi Hetaera e porta a Sire Arkkoroc la Testa Insanguinata di Hetaera, la Testa Percossa di Hetaera e la Testa Contusa di Hetaera.",
    [3511] = "Riporta la tempra a Loramus Thalipedes.\\n",
    [3520] = "Cattura gli spiriti di 3 Stridenti a Feralas, poi torna da Yeh'kinya a Porto degli Spargifumo.",
    [3527] = "Porta la Prima e la Seconda Tavoletta di Mosh'aru a Yeh'kinya a Tanaris.",
    [3528] = "Porta l'Uovo di Hakkar Pieno a Yeh'kinya a Tanaris.",
    [3602] = "Recupera venti frammenti di Azsharite Cristallizzata nell'Azshara meridionale. Puoi usare il Vilsegugio per \"fiutare\" la posizione dei giacimenti ben nascosti.$B$BTorna da Loramus una volta completato il compito.\\n",
    [3621] = "Porta il Carico a Galvan l'Antico nella Valle di Rovotorto.",
    [3625] = "Aspetta che Galvan finisca di forgiare le armi.",
    [3626] = "Torna dall'Eroe dell'Orda Caduto.",
    [3627] = "Uccidi Grol il Distruttore, Dama Sevine e l'Arcimago Allistarj. Prendi dai loro cadaveri l'Amuleto di Grol, l'Amuleto di Sevine e l'Amuleto di Allistarj.$B$BRicorda di USARE le tue Armi vil incantate di azsharite per indebolire la triade. Altrimenti non possono essere uccisi, ma usale con saggezza...\\n",
    [3628] = "Distruggi Razelikh il Profanatore e porta il Corno Mozzato del Profanatore all'Eroe dell'Orda Caduto. Dovrai anche consegnare la Protezione del Profanatore, così che l'Eroe Caduto possa distruggerla e impedire che finisca nelle mani sbagliate.\\n",
    [3631] = "Parla con Strahad Farsan nelle Savane.",
    [3701] = "Avventurati alle Rovine di Thaurissan nelle Steppe Ardenti e recupera informazioni dalle Reliquie di Thaurissan. Torna dalla Storica Reale Archesonus quando avrai recuperato le informazioni.",
    [3702] = "Ascolta la Storica Reale Archesonus mentre narra la storia di Thaurissan.",
    [3783] = "Raccogli 10 Pellicce di Yeti Spesse per Umi Cavocurvo a Lungavista.",
    [3801] = "Parla con Franclorn Forgiabruna se ti interessa ottenere una chiave per la città vera e propria.",
    [3802] = "Uccidi Fineous Forgiascura e recupera il grande martello Ferrovile. Porta Ferrovile al Santuario di Thaurissan e posalo sulla statua di Franclorn Forgiabruna.",
    [3844] = "Cerca nello stagno un indizio su chi possa essere il proprietario di questa zattera distrutta.",
    [3845] = "Esamina gli oggetti nello zaino e portali al loro proprietario.",
    [3903] = "Parla con Milly Osworth.",
    [3904] = "Porta 8 casse del raccolto di Milly a Milly Osworth all'Abbazia della Contea del Nord.",
    [3907] = "Entra nei Sotterranei di Roccianera e rintraccia Sire Incendius. Uccidilo e porta a Cortonante qualsiasi fonte di informazioni tu riesca a trovare.",
    [3908] = "Porta la spada di Linken a Donova Pestaneve a Fontefredda.",
    [3909] = "Cerca Gregan Brewspewer nel Feralas settentrionale. Fatti spiegare da lui come ottenere l'Elisir di Videre, poi torna da Donova Pestaneve a Fontefredda.",
    [3912] = "Recati al cimitero fuori Meccania e usa l'Elisir di Videre. Segui il resto delle istruzioni di Donova per trovare Gaeriyan.",
    [3913] = "Resuscita, poi cerca la lapide che Gaeriyan ti ha detto di trovare.",
    [3914] = "Consegna la Spada Superiore di Linken a Linken nel Cratere di Un'Goro.",
    [3941] = "Trova J.D. Collie nella grotta del Rifugio dei Grant.",
    [3942] = "Trova Eridan Brezzastrale nel Vilbosco meridionale.",
    [3961] = "Porta il Totem d'Argento di Aquementas a Linken al Rifugio dei Grant.",
    [3962] = "Recati al Rilievo del Magma Colante, a sud del Rifugio dei Grant.$B$BTrova Blazerunner e usa il totem per rimuovere la sua aura protettiva. Dopo averlo sconfitto, prendi la Fiamma Dorata dalla grotta.",
    [3981] = "Trova il Comandante Gor'shak nei Sotterranei di Roccianera.$B$BRicordi che il rozzo disegno dell'orco aveva delle sbarre tracciate sopra il ritratto. Forse dovresti cercare una specie di prigione.",
    [3982] = "Difendi Gor'shak.",
    [4001] = "Parla con Kharan Mighthammer e raccogli informazioni sul rapimento della Principessa Moira Barbabronzea. Porta queste informazioni a Thrall a Orgrimmar.$B$BRicordi che Gor'shak ha detto che Kharan è rinchiuso in una cella lì vicino.\\n",
    [4002] = "Parla con Thrall se vuoi intraprendere la missione che ha pianificato.",
    [4003] = "Uccidi l'Imperatore Dagran Thaurissan e libera la Principessa Moira Barbabronzea dal suo malvagio incantesimo.\\n",
    [4004] = "Torna da Thrall!\\n",
    [4005] = "Porta il Libro di Aquor, gli Artigli Argentei e il Cuore di Alberferro a Tanaris.$B$BUsa il Libro di Aquor per evocare Aquementas.$B$BQuando avrai il totem completo, portalo a J.D. Collie al Rifugio dei Grant.",
    [4024] = "Recati ai Sotterranei di Roccianera e uccidi Bael'gar.$B$BSai soltanto che il gigante si trova all'interno dei Sotterranei di Roccianera. Ricordati di usare la Muta Alterata dello Stormo Nero sui resti di Bael'gar per catturare l'Essenza Ardente.$B$BPorta l'Essenza Ardente Intrappolata a Cyrus Therepentous.",
    [4063] = "Trova e uccidi Argelmach il Signore dei Golem. Porta la sua testa a Lotwil. Dovrai anche raccogliere 10 Nuclei Elementali Intatti dai Golem Razziarabbia e dai Costrutti Araldici della Guerra che proteggono Argelmach. Lo sai perché hai poteri psichici.",
    [4081] = "Avventurati nei Sotterranei di Roccianera e distruggi i vili aggressori!$B$BIl Signore della Guerra Zannatruce vuole che tu uccida 15 Armigeri Forgiafuria, 10 Custodi Forgiafuria e 5 Coscritti Forgiafuria. Torna da lui una volta completato il compito.",
    [4082] = "Avventurati nei Sotterranei di Roccianera e distruggi i vili aggressori!$B$BIl Signore della Guerra Zannatruce vuole che tu uccida 10 Medici Forgiafuria, 10 Soldati Forgiafuria e 10 Ufficiali Forgiafuria. Torna da lui una volta completato il compito.",
    [4083] = "Il Calice Spettrale fluttua in aria, salendo e scendendo lentamente... quasi a seguire il ritmo di un cuore morente.",
    [4084] = "Raccogli 11 Artigli Argentei e 1 Cuore di Alberferro per Eridan Brezzastrale nel Vilbosco.",
    [4121] = "Scorta il tuo prigioniero, Grark Lorkrub, attraverso le Steppe Ardenti e il Massiccio Roccianera fino alla Gorgia Rovente.$B$BRicordi che Lexlort aveva detto che i suoi uomini avrebbero aspettato dall'altra parte per prendere in custodia Grark.$B$BDovrai anche consegnare a Lexlort le tue Manette di Torio.",
    [4122] = "Recati nelle Steppe Ardenti e trova Grark Lorkrub. Ricordi che Lexlort aveva detto che era stato visto l'ultima volta in un'enorme fortezza dei Roccianera.$B$BQuando avrai trovato Grark Lorkrub, usa le Manette di Torio per legarlo, poi riportalo attraverso il Massiccio Roccianera fino alla Gorgia Rovente. Gli uomini di Lexlort aspetteranno dall'altra parte per prenderlo in custodia.",
    [4123] = "Porta il Cuore della Montagna a Maxwort Granscintilla nelle Steppe Ardenti.",
    [4124] = "Parla con Ginro Cuorfavilla alla Roccaforte di Piumaluna.",
    [4125] = "Trova la barca del corriere da qualche parte lungo la costa di Feralas.",
    [4126] = "Porta la Ricetta Perduta della Birratuono a Ragnar Birratuono a Kharanos.",
    [4127] = "Torna alla Roccaforte di Piumaluna e mostra a Ginro Cuorfavilla il Coltello Abbandonato che hai trovato.",
    [4128] = "Parla con Ragnar Birratuono.",
    [4129] = "Porta il Coltello Abbandonato a Quintis Tordigiada alla Roccaforte di Piumaluna.",
    [4130] = "Parla con Ginro Cuorfavilla alla Roccaforte di Piumaluna.",
    [4131] = "Perlustra gli accampamenti degli gnoll Zampalegno nel Feralas meridionale in cerca di tracce degli effetti personali del corriere o del corriere stesso.",
    [4132] = "Recati ai Sotterranei di Roccianera e uccidi il Generale Forgiarabbia! Torna dal Signore della Guerra Zannatruce una volta completato il compito.",
    [4133] = "Parla con la Maga dell'Ombra Vivian Lagrave a Kargath.",
    [4134] = "Porta la Ricetta Perduta della Birratuono a Vivian Lagrave a Kargath.",
    [4135] = "Ora che hai scoperto l'ultima posizione nota di Raschal, continua a cercare lui o i suoi resti nelle Profondità Contorte. Secondo il biglietto, si trovano a sud degli accampamenti degli gnoll Zampalegno.",
    [4136] = "Porta la Testa di Ribbly a Yuka Giravite nelle Steppe Ardenti.",
    [4182] = "Uccidi 15 Cuccioli di Drago Neri, 10 Draconidi Neri, 4 Wyrmidi Neri e 1 Draco Nero. Torna da Helendis Sinuocorno una volta completato il compito.",
    [4183] = "Recati a Borgolago e consegna la Lettera di Helendis Sinuocorno al Magistrato Solomon.",
    [4184] = "Recati a Roccavento e consegna la Supplica di Solomon al Gran Signore Bolvar Domadraghi.$B$BBolvar risiede nel Forte di Roccavento.",
    [4185] = "Parla con il Gran Signore Bolvar Domadraghi dopo aver parlato con Dama Katrana Prestor.",
    [4186] = "Porta il Decreto di Bolvar al Magistrato Solomon a Borgolago.\\n",
    [4201] = "Porta 4 Sangue di Grommash, 10 Vene d'Argento Gigante e la Fiala Piena di Nagmara alla Signora Nagmara nei Sotterranei di Roccianera.",
    [4223] = "Parla con il Maresciallo Maxwell nelle Steppe Ardenti.",
    [4224] = "Parla con John il Malconcio per scoprire la sorte del Maresciallo Windsor e torna dal Maresciallo Maxwell una volta completato il compito.$B$BRicordi che il Maresciallo Maxwell ti ha detto di cercarlo in una grotta a nord.",
    [4241] = "Recati al Massiccio Roccianera, a nord-ovest, ed entra nei Sotterranei di Roccianera. Scopri che fine ha fatto il Maresciallo Windsor.$B$BRicordi che John il Malconcio parlava di Windsor trascinato in una prigione.",
    [4242] = "Dai la brutta notizia al Maresciallo Maxwell.",
    [4263] = "Trova Sire Incendius nei Sotterranei di Roccianera e distruggilo!",
    [4264] = "Potresti aver trovato qualcosa che il Maresciallo Windsor sarebbe interessato a vedere. Dopotutto, forse c'è ancora speranza.",
    [4265] = "Libera Raschal dall'alveare degli Zukk'ash.$B$BTorna da Ginro Cuorfavilla alla Roccaforte di Piumaluna e digli che Raschal è vivo e vegeto.",
    [4266] = "Parla con Shandris Piumaluna alla Roccaforte di Piumaluna.",
    [4267] = "Porta il Rapporto di Raschal a Gracina Spiritmight a Darnassus.",
    [4281] = "Porta il Pacco non consegnato a Falfindel Waywarder a Thalanaar.",
    [4282] = "Riporta le informazioni perdute del Maresciallo Windsor.$B$BIl Maresciallo Windsor crede che le informazioni siano custodite dal Signore dei Golem Argelmach e dal Generale Forgiarabbia.",
    [4286] = "Recati ai Sotterranei di Roccianera e recupera 20 Marsupi dei Ferroscuro. Torna da Oralius una volta completato il compito. Immagini che siano i nani Ferroscuro dei Sotterranei di Roccianera a portare con sé questi aggeggi chiamati \"marsupi\".",
    [4322] = "Aiuta il Maresciallo Windsor a recuperare il suo equipaggiamento e a liberare i suoi amici. Torna dal Maresciallo Maxwell se ci riesci.",
    [4324] = "Parla con Yuka Giravite nelle Steppe Ardenti.",
    [4341] = "Recati ai Sotterranei di Roccianera e trova Kharan Mighthammer.$B$BIl Re ha detto che Kharan è tenuto prigioniero lì: forse dovresti cercare una prigione.",
    [4342] = "Ascolta Kharan Mighthammer mentre racconta la sua storia.",
    [4361] = "Torna a Forgiardente e dai la brutta notizia a Re Magni Barbabronzea.",
    [4362] = "Torna ai Sotterranei di Roccianera e salva la Principessa Moira Barbabronzea dalle grinfie malvagie dell'Imperatore Dagran Thaurissan.\\n",
    [4363] = "Torna a Forgiardente e parla con Re Magni Barbabronzea.",
    [4487] = "Parla con Strahad Farsan a Porto Paranco.",
    [4488] = "Parla con Strahad Farsan a Porto Paranco.",
    [4489] = "Parla con Strahad Farsan a Porto Paranco.",
    [4490] = "Parla con Strahad Farsan a Porto Paranco per imparare a evocare un Vildestriero.",
    [4701] = "Recati ai Bastioni di Roccianera e distruggi la fonte della minaccia dei worg. Mentre ti allontanavi, Helendis ha gridato un nome: Halycon. È il nome con cui gli orchi chiamano il worg.",
    [4724] = "Uccidi Halycon, matriarca del branco dei worg della Scure Rossa.",
    [4729] = "Recati ai Bastioni di Roccianera e trova dei Cuccioli di Worg della Scure Rossa. Usa la gabbia per trasportare quelle feroci bestiole. Porta un Cucciolo di Worg Ingabbiato a Kibler.",
    [4734] = "Usa il Prototipo di Uovometro su un uovo nella Corveria.",
    [4735] = "Porta 8 Uova di Drago Raccolte e il Modulo Collettronico a Tinkee Vapormarcio al Cimiero Ardente, nelle Steppe Ardenti.",
    [4742] = "Trova le tre gemme del comando: la Gemma dei Bruciaspina, la Gemma degli Spiraroccia e la Gemma degli Scurerossa. Riportale ad Acride insieme al Sigillo dell'Ascesa Disadorno.$B$BI Generali, secondo quanto ti ha detto Acride, sono: il Maestro di Guerra Voone dei Bruciaspina, il Gran Signore Omokk degli Spiraroccia e il Supremo Dragthalak degli Scurerossa.",
    [4743] = "Recati al Brago dei Dragoni, ad Acquemorte. Trova l'antico draco Braceardente e colpiscilo senza pietà finché la sua volontà non sarà spezzata.$B$BÈ in quel momento che dovrai porre il Sigillo dell'Ascesa Non Forgiato davanti alla grande bestia. Poi dovrai usare rapidamente il Globo dell'Energia Draconica sulla sua forma indebolita e prendere il controllo delle sue facoltà mentali. Controlla la bestia e costringila a scagliare le Fiamme dello Stormo Nero sul Sigillo dell'Ascesa Non Forgiato!",
    [4764] = "Porta la Fibbia del Portarovina a Mayara Alachiara nelle Steppe Ardenti.",
    [4765] = "Porta la Cassa di Crestafonda a Remington Crestafonda a Roccavento.",
    [4766] = "Parla con Mayara Alachiara nelle Steppe Ardenti.",
    [4768] = "Porta la Tavoletta di Pietra Nera alla Maga dell'Ombra Vivian Lagrave a Kargath.",
    [4769] = "Parla con la Maga dell'Ombra Vivian Lagrave.",
    [4771] = "Colloca la Trappola di Alexi nella Sala d'Osservazione di Scholomance. Sconfiggi Vectus, poi torna da Betina Lucestrema.",
    [4787] = "Porta l'uovo antico a Yeh'kinya a Tanaris.",
    [4788] = "Porta la Quinta e la Sesta Tavoletta di Mosh'aru al Prospettore Scarpaferrea a Tanaris.",
    [4862] = "Recati ai Bastioni di Roccianera e raccogli 15 Uova del Ragno dei Bastioni per Kibler.$B$BA quanto pare, queste uova si trovano vicino ai ragni.",
    [4866] = "Nel cuore dei Bastioni di Roccianera troverai Madre Bruciatela. Affrontala e fatti avvelenare. Con ogni probabilità dovrai anche ucciderla. Quando avrai il veleno in corpo, torna da John il Malconcio, così potrà \"mungerti\".",
    [4867] = "Leggi la Pergamena di Warosh. Porta il Mojo di Warosh a Warosh.",
    [4903] = "Uccidi il Gran Signore Omokk, il Maestro di Guerra Voone e il Sommo Signore Wyrmthalak. Recupera i Documenti Importanti dei Roccianera. Torna dal Signore della Guerra Zannatruce a Kargath una volta compiuta la missione.",
    [4907] = "Parla con Tinkee Vapormarcio.",
    [4921] = "Trova la moglie di Mankrik, poi torna da lui al Crocevia.",
    [4941] = "Parla con Eitrigg a Orgrimmar. Dopo aver discusso la questione con Eitrigg, chiedi consiglio a Thrall.$B$BRicordi di aver visto Eitrigg nella sala di Thrall.",
    [4974] = "Recati ai Bastioni di Roccianera e uccidi il Capoguerra Rend Manonera. Prendi la sua testa e torna a Orgrimmar.",
    [4981] = "Recati ai Bastioni di Roccianera e scopri cos'è successo a Bijou.",
    [4982] = "Trova i Beni di Bijou e riportaglieli. Ricordi che ti ha detto di averli nascosti al piano più basso della città.",
    [4983] = "Riporta il Rapporto di Ricognizione di Bijou al Gran Maestro Lexlort a Kargath.",
    [5001] = "Trova i Beni di Bijou e riportaglieli. Buona fortuna!",
    [5002] = "Recati nelle Steppe Ardenti e consegna l'Informazione di Bijou al Maresciallo Maxwell.",
    [5047] = "Parla con Malyfous Martelnero a Lungavista.",
    [5061] = "Torna a Darnassus e mostra a Mathrengyl Domaorsi il Ciondolo del Leone Marino.",
    [5065] = "Porta la Terza e la Quarta Tavoletta di Mosh'aru al Prospettore Scarpaferrea a Tanaris.",
    [5081] = "Recati ai Bastioni di Roccianera e distruggi il Maestro di Guerra Voone, il Gran Signore Omokk e il Supremo Dragthalak. Torna dal Maresciallo Maxwell una volta completato il compito.",
    [5089] = "Porta il Comando del Generale Drakkisath al Maresciallo Maxwell nelle Steppe Ardenti.",
    [5096] = "Raggiungi il campo base della Crociata Scarlatta tra il Campo di Vilpietra e le Lacrime di Dalson e distruggi la loro tenda di comando.$B$BPianta lo Stendardo del Flagello nell'accampamento, poi torna dal Gran Esecutore Derrington alla Granbarricata, Terre Infette Occidentali.",
    [5097] = "Usando la Torcia di Segnalazione, segna ogni torre di Andorhal: per riuscirci dovrai trovarti sulla soglia della torre.$B$BUna volta segnate tutte e quattro le torri, riporta la Torcia di Segnalazione al Comandante Ashlam Pugnoprode all'Accampamento di Ventofreddo, Terre Infette Occidentali.",
    [5098] = "Usando la Torcia di Segnalazione, segna ogni torre di Andorhal: per riuscirci dovrai trovarti sulla soglia della torre.$B$BUna volta segnate tutte e quattro le torri, riporta la Torcia di Segnalazione al Gran Esecutore Derrington alla Granbarricata, Terre Infette Occidentali.",
    [5102] = "Recati ai Bastioni di Roccianera e distruggi il Generale Drakkisath. Torna dal Maresciallo Maxwell una volta completato il compito.",
    [5122] = "Il potere di questa cappella mi dà la forza di resistere alla corruzione nel mio cuore. Se la lascio, diventerò un cavaliere della morte. Ma esiste un medaglione, il Medaglione della Fede, che mi darà la forza necessaria per andarmene.$B$BTi prego, $N, recupera il medaglione. È custodito da Malor lo Zelante, un folle membro della Confraternita Scarlatta che risiede nelle profondità del Bastione Scarlatto, nella parte occidentale di Stratholme.",
    [5125] = "$N, sto morendo... ma la mia anima è salva. Per questo ti devo più di quanto le parole possano dire. Ti prego, prendi questo... e continua a combattere con coraggio, $C!",
    [5127] = "Recati ai Bastioni di Roccianera e trova Goraluk Spaccaroccia. Uccidilo, poi usa la Picca Macchiata di Sangue sul suo cadavere. Quando la sua anima sarà stata assorbita, la picca diventerà la Picca dell'Anima Macchiata.$B$BDovrai anche trovare il Pettorale Corazzato Runico Grezzo.$B$BPorta sia la Picca dell'Anima Macchiata sia il Pettorale Corazzato Runico Grezzo a Lorax a Fontefredda.",
    [5142] = "Trova Pamela Tracciarossa.",
    [5149] = "Trova la bambola di Pamela.",
    [5152] = "Parla con Marlene, a sud delle Rovine di Andorhal.",
    [5153] = "Porta l'Anello Nuziale di Joseph a Cromie.",
    [5154] = "Porta gli annali del Borgo di Darrow a Cromie ad Andorhal.",
    [5160] = "Recati a Fontefredda e trova Haleh. Consegnale la scaglia di Awbee.",
    [5163] = "Prendi lo Yeti Meccanico di Umi e usalo per spaventare i suoi amici:$B$BLegacki a Lungavista (Fontefredda)$BSprizzy a Meccania (Tanaris)$BQuixxil al Rifugio dei Grant (Cratere di Un'Goro)$B$BQuando hai finito, riporta lo Yeti Meccanico a Umi.",
    [5168] = "Porta il Libram di Davil e lo Scudo di Tracciarossa a Carlin Tracciarossa.",
    [5181] = "Porta il Teschio di Horgus e la Spada Spezzata di Marduk a Carlin Tracciarossa alla Cappella della Luce.",
    [5206] = "Porta 5 Teschi Risonanti e il Cristallo Mistico a Carlin Tracciarossa nelle Terre Infette Orientali.",
    [5210] = "Porta gli annali estesi del Borgo di Darrow a Carlin Tracciarossa nelle Terre Infette Orientali.",
    [5211] = "Libera 15 Spiriti del Borgo di Darrow e torna da Carlin Tracciarossa.",
    [5212] = "Recupera 20 Campioni di Carne Infetta a Stratholme e portali a Betina Lucestrema. Immagini che qualsiasi creatura di Stratholme possa fornirti un campione di quella carne.",
    [5213] = "Recati a Stratholme e perlustra gli ziggurat. Trova i nuovi Dati del Flagello e portali a Betina Lucestrema.",
    [5214] = "Trova la tabaccheria di Ezra Grimm a Stratholme e recupera una scatola di Tabacco Premium di Grimm. Torna da Smokey LaRue una volta completato il compito.",
    [5241] = "Trova Carlin Tracciarossa.",
    [5243] = "Recati a Stratholme, a nord. Fruga nelle casse di provviste sparse per la città e recupera 5 fiale di Acqua Santa di Stratholme. Torna da Leonid Bartholomew il Riverito quando avrai raccolto abbastanza fluido benedetto.",
    [5251] = "Recati a Stratholme e trova l'Archivista Galford della Crociata Scarlatta. Distruggilo e brucia l'Archivio Scarlatto.",
    [5262] = "Porta la Testa di Balnazzar al Duca Nicholas Zverenhoff nelle Terre Infette Orientali.",
    [5263] = "Avventurati a Stratholme e distruggi il Barone Rivendare. Prendi la sua testa e torna dal Duca Nicholas Zverenhoff.\\n",
    [5282] = "Usa il Fucile di Egan sui cittadini fantasma e spettrali di Stratholme. Quando le anime inquiete si saranno liberate dai loro gusci spettrali, usa di nuovo il fucile: saranno finalmente libere!$B$BLibera 15 Anime Inquiete e torna da Egan.",
    [5341] = "Avventurati a Scholomance e recupera la fortuna della famiglia Barov. Questa fortuna è composta da quattro atti di proprietà: l'Atto di Caer Darrow, l'Atto di Brill, l'Atto di Mulino di Tarren e l'Atto di Riva del Sud. Torna da Alexi Barov una volta completato il compito.",
    [5342] = "Recati all'Accampamento di Ventofreddo, in territorio dell'Alleanza, e assassina Weldon Barov. Prendi la sua testa e torna da Alexi Barov.$B$BFai attenzione: probabilmente Weldon sarà ben protetto dalla feccia dell'Alleanza.",
    [5343] = "Avventurati a Scholomance e recupera la fortuna della famiglia Barov. Questa fortuna è composta da quattro atti di proprietà: l'Atto di Caer Darrow, l'Atto di Brill, l'Atto di Mulino di Tarren e l'Atto di Riva del Sud. Torna da Weldon Barov una volta completato il compito.",
    [5344] = "Recati alla Granbarricata, in territorio dell'Orda, e assassina Alexi Barov. Prendi la sua testa e torna da Weldon Barov.$B$BFai attenzione: probabilmente Alexi sarà ben protetto dalla marmaglia dell'Orda.",
    [5382] = "Trova il Dottor Theolen Krastinov all'interno di Scholomance. Distruggilo, poi brucia i Resti di Eva Sarkhoff e i Resti di Lucien Sarkhoff. Torna da Eva Sarkhoff una volta completato il compito.\\n",
    [5383] = "Porta la Borsa degli Orrori a Eva Sarkhoff a Caer Darrow.",
    [5384] = "Torna a Scholomance con il Sangue di Innocenti. Trova il portico e metti il Sangue di Innocenti nel braciere. Kirtonos verrà a banchettare con la tua anima.$B$BCombatti con valore, non cedere di un passo! Distruggi Kirtonos e torna da Eva Sarkhoff.\\n",
    [5461] = "Recati negli Altopiani d'Arathi, tra le rovine di Stromgarde. Cerca a Stromgarde un Cimelio del Ricordo. Se trovi un oggetto simile, portalo al Magistrato Marduke.",
    [5462] = "Recati a Speranza della Luce nelle Terre Infette Orientali e cerca Leonid Barthalomew il Reverito. Mostragli il Cimelio del Ricordo e raccontagli tutto ciò che hai scoperto.",
    [5463] = "Recati a Stratholme e trova il Dono di Menethil. Posa il Cimelio del Ricordo sul suolo profano.",
    [5464] = "Porta il Cimelio vincolato all'anima a Leonid Barthalomew nelle Terre Infette Orientali.",
    [5465] = "Torna dal Magistrato Marduke a Caer Darrow. Mostragli il Cimelio vincolato all'anima.",
    [5466] = "Trova Ras Soffiogelo a Scholomance. Quando l'avrai trovato, usa il Cimelio vincolato all'anima sul suo volto non morto. Se riesci a farlo tornare mortale, abbattilo e recupera la Testa Umana di Ras Soffiogelo. Riporta la testa al Magistrato Marduke.",
    [5514] = "Porta i Frammenti scheletrici impregnati e 15 monete d'oro a Krinkle Ferrofiz a Meccania.",
    [5515] = "Trova Jandice Barov a Scholomance e distruggila. Recupera dal suo cadavere la borsa degli orrori di Krastinov. Riporta la borsa a Eva Sarkhoff.",
    [5518] = "Porta 4 Rotoli di Telarunica, 8 pezzi di Cuoio Duro, 2 Fili Runici e il Colorante Ogre a Knot Pallapiede. Al momento è incatenato nell'ala dei Gordok di Maglio Infausto.",
    [5525] = "Si chiama Chiave delle Catene di Gordok... o almeno è così che continuano a chiamarla questi \"simpatici bestioni\". Credo che potrebbe averla uno qualsiasi degli ogre, ma non so se ce l'abbia qualcuno in particolare. Forse le guardie hanno più probabilità di averne una...$B$BMa cosa sto dicendo? Ce l'hai già, vero?! È quella lì??!",
    [5528] = "Tu ora grande capo, così tu avere assaggio gratis di mie birre migliori! Queste bevande ti tirano su E ti danno bella sbronza! Queste sono quelle buone, capo... tu prova e dillo a Kreeg!",
    [5529] = "Uccidi 20 esemplari di Prole Appestata, poi torna da Betina Lucestrema alla Cappella della Luce.",
    [5531] = "Porta le Uova Congelate a Betina Lucestrema.",
    [5533] = "Parla con l'Alchimista Arbington alla Gola di Ventofreddo, Terre Infette Occidentali.",
    [5537] = "Porta 15 Frammenti scheletrici all'Alchimista Arbington alla Gola di Ventofreddo, Terre Infette Occidentali.",
    [5538] = "Porta i Frammenti scheletrici impregnati e 15 monete d'oro a Krinkle Ferrofiz a Meccania.",
    [5582] = "Porta la Scaglia di Drago Sano a Betina Lucestrema alla Cappella della Luce, nelle Terre Infette Orientali.",
    [5601] = "Trova Pamela Tracciarossa al Borgo di Darrow.",
    [5721] = "Posa il Fagotto di Reliquie nella Piazza Centrale del Borgo di Darrow.$B$BImpedisci la morte di Davil Lightfire fino alla morte di Horgus.$B$BImpedisci la morte del Capitano Tracciarossa finché non compare Tracciarossa il Corrotto.$B$BSconfiggi Tracciarossa il Corrotto.$B$BParla con lo spirito di Joseph Tracciarossa quando compare nella piazza centrale, poi parla con Pamela a casa sua.",
    [5742] = "Ascolta ciò che Tirion Fordring ha da dire.",
    [5762] = "Porta la Cassa di Kravel a Hemet Nesingwary a Rovotorto.",
    [5763] = "Porta il Corno di Kodo di Roon a Hemet Nesingwary a Rovotorto.",
    [5781] = "Recati alla Cripta di Zaeldarr, nella parte più meridionale delle Terre Infette Orientali, e recupera il Martello di Taelan. Torna da Tirion Fordring una volta raggiunto il tuo obiettivo.",
    [5801] = "Porta lo Stampo della Chiave Scheletrica e 2 Lingotti di Torio in cima al Rilievo del Magma Colante nel Cratere di Un'Goro. Usa lo Stampo della Chiave Scheletrica presso il lago di lava per forgiare la Chiave Scheletrica Incompleta.$B$BPorta la Chiave Scheletrica Incompleta all'Alchimista Arbington alla Gola di Ventofreddo, Terre Infette Occidentali.",
    [5802] = "Porta lo Stampo della Chiave Scheletrica e 2 Lingotti di Torio in cima al Rilievo del Magma Colante nel Cratere di Un'Goro. Usa lo Stampo della Chiave Scheletrica presso il lago di lava per forgiare la Chiave Scheletrica Incompleta.$B$BPorta la Chiave Scheletrica Incompleta allo Speziale Alienatus alla Granbarricata, Terre Infette Occidentali.",
    [5803] = "Distruggi Araj l'Evocatore e porta lo scarabeo di Araj all'Alchimista Arbington alla Gola di Ventofreddo, Terre Infette Occidentali.",
    [5804] = "Distruggi Araj l'Evocatore e porta lo scarabeo di Araj allo Speziale Alienatus alla Granbarricata, Terre Infette Occidentali.",
    [5845] = "Recati a Valnordia, nella regione nordorientale delle Terre Infette Orientali, e recupera il Simbolo di onore perduto. Torna da Tirion Fordring una volta raggiunto il tuo obiettivo.",
    [5846] = "Recati sull'isola di Caer Darrow, nella regione centro-meridionale delle Terre Infette, e cerca indizi su dove si trovi il dipinto.",
    [5848] = "Recati a Stratholme, nella parte settentrionale delle Terre Infette. Nel Bastione Scarlatto troverai il dipinto \"Di amore e famiglia\", nascosto dietro un altro dipinto che raffigura le lune gemelle del nostro mondo.$B$BRiporta il dipinto a Tirion Fordring.",
    [5861] = "Recati al Sepolcro di Uther, nelle Terre Infette meridionali. Mostra a Myranda la Strega il Dono di Tirion.",
    [5862] = "Parla con Myranda per ottenere l'Illusione Scarlatta. Recati a Valsalda sotto l'effetto dell'Illusione Scarlatta e consegna il Dono di Tirion al Gran Signore Taelan Fordring.$B$BValsalda si trova a nord; Taelan dovrebbe essere all'interno del Forte Mardenholde.",
    [5921] = "Usa l'incantesimo \"Teletrasporto: Radaluna\" per recarti a Radaluna. Al tuo arrivo, parla con Dendrite Ardistella nel villaggio di Nottequieta.",
    [5922] = "Usa l'incantesimo \"Teletrasporto: Radaluna\" per recarti a Radaluna. Al tuo arrivo, parla con Dendrite Ardistella nel villaggio di Nottequieta.",
    [5923] = "Parla con Mathrengyl Domaorsi nell'Enclave Cenariana, Darnassus.",
    [5924] = "Parla con Mathrengyl Domaorsi nell'Enclave Cenariana, Darnassus.",
    [5925] = "Parla con Mathrengyl Domaorsi nell'Enclave Cenariana, Darnassus.",
    [5926] = "Parla con Turak Totem Runico sull'Altura degli Anziani di Picco del Tuono.",
    [5927] = "Parla con Turak Totem Runico sull'Altura degli Anziani di Picco del Tuono.",
    [5928] = "Parla con Turak Totem Runico sull'Altura degli Anziani di Picco del Tuono.",
    [5929] = "Cerca lo Spirito del Grande Orso nella zona nordoccidentale di Radaluna e scopri cosa ha da insegnarti sulla natura dell'orso. Al termine, torna da Dendrite Ardistella a Nottequieta, Radaluna.",
    [5930] = "Cerca lo Spirito del Grande Orso nella zona nordoccidentale di Radaluna e scopri cosa ha da insegnarti sulla natura dell'orso. Al termine, torna da Dendrite Ardistella a Nottequieta, Radaluna.",
    [5931] = "Torna a Darnassus e parla con Mathrengyl Domaorsi nell'Enclave Cenariana.",
    [5932] = "Torna a Picco del Tuono e parla con Turak Totem Runico sull'Altura degli Anziani.",
    [5941] = "Porta il Fagotto di Reliquie a Cromie ad Andorhal.",
    [5942] = "Porta la Chiave di Joseph al Forziere di Joseph.",
    [5944] = "Scorta Taelan Fordring fuori da Valsalda.",
    [6001] = "Usa la Polvere di Luna Cenariana sulla Pietra dei Lunagufi di Auberdine per far comparire Lunaclaw. Dovrai quindi affrontare Lunaclaw e conquistare la forza del corpo e del cuore che possiede.$B$BQuando avrai finito, parla con Mathrengyl Domaorsi a Darnassus.",
    [6002] = "Usa la Polvere Lunare Cenariana sulla Pietra dei Lunagufi tra Mulgore e le Savane per far comparire Lunaclaw. Dovrai quindi affrontare Lunaclaw e conquistare la forza del corpo e del cuore che possiede.$B$BQuando avrai finito, parla con Turak Totem Runico a Picco del Tuono.",
    [6004] = "Uccidi 2 Medici Scarlatti, 2 Cacciatori Scarlatti, 2 Magi Scarlatti e 2 Cavalieri Scarlatti, poi torna da Kirsta Ombrafonda nelle Terre Infette Occidentali.",
    [6023] = "Uccidi la Predatrice Radley e il Cavaliere Durgen, poi torna da Kirsta Ombrafonda nelle Terre Infette Occidentali.",
    [6025] = "Entra a Valsalda e trova un punto d'osservazione elevato da cui scrutare la città e valutare le forze della Crociata Scarlatta, poi torna da Kirsta Ombrafonda nelle Terre Infette Occidentali.",
    [6061] = "Usa la Bacchetta dell'Addomesticamento per addomesticare un Trampoliere delle Pianure Adulto. Fai pratica con le tue abilità, poi riporta la Bacchetta dell'Addomesticamento a Yaw Chioma Rasa al Villaggio di Zoccolo Sanguinario.",
    [6062] = "Usa la Bacchetta dell'Addomesticamento per addomesticare un Cinghiale Chiazzato Feroce. Fai pratica con le tue abilità, poi riporta la Bacchetta dell'Addomesticamento a Thotar a Tranciacolle.",
    [6063] = "Usa la Bacchetta dell'Addomesticamento per addomesticare un Insidiatore di Boscotela. Fai pratica con le tue abilità, poi riporta la Bacchetta dell'Addomesticamento a Dazalar a Dolanaar.",
    [6064] = "Usa la Bacchetta dell'Addomesticamento per addomesticare un Grosso Cinghiale delle Rupi. Fai pratica con le tue abilità, poi riporta la Bacchetta dell'Addomesticamento a Grif Cuorselvaggio a Kharanos.",
    [6065] = "Parla con Yaw Chioma Rasa al Villaggio di Zoccolo Sanguinario.",
    [6066] = "Parla con Yaw Chioma Rasa al Villaggio di Zoccolo Sanguinario.",
    [6067] = "Parla con Yaw Chioma Rasa al Villaggio di Zoccolo Sanguinario.",
    [6068] = "Parla con Thotar a Tranciacolle.",
    [6069] = "Parla con Thotar a Tranciacolle.",
    [6070] = "Parla con Thotar a Tranciacolle.",
    [6071] = "Parla con Dazalar a Dolanaar.",
    [6072] = "Parla con Dazalar a Dolanaar.",
    [6073] = "Parla con Dazalar a Dolanaar.",
    [6074] = "Parla con Grif Cuorselvaggio a Kharanos.",
    [6075] = "Parla con Grif Cuorselvaggio a Kharanos.",
    [6076] = "Parla con Grif Cuorselvaggio a Kharanos.",
    [6081] = "Parla con Ormak Grimshot a Orgrimmar.",
    [6082] = "Usa la Bacchetta dell'Addomesticamento per addomesticare uno Scorpide Corazzato. Fai pratica con le tue abilità, poi torna da Thotar a Tranciacolle.",
    [6083] = "Usa la Bacchetta dell'Addomesticamento per addomesticare un Granchio della Risacca. Fai pratica con le tue abilità, poi riporta la Bacchetta dell'Addomesticamento a Thotar a Tranciacolle.",
    [6084] = "Usa la Bacchetta dell'Addomesticamento per addomesticare un Leopardo delle Nevi. Fai pratica con le tue abilità, poi torna da Grif Cuorselvaggio a Kharanos.",
    [6085] = "Usa la Bacchetta dell'Addomesticamento per addomesticare un Orso Artiglio di Ghiaccio. Fai pratica con le tue abilità, poi riporta la Bacchetta dell'Addomesticamento a Grif Cuorselvaggio a Kharanos.",
    [6086] = "Parla con Belia Thundergranite a Forgiardente.",
    [6087] = "Usa la Bacchetta dell'Addomesticamento per addomesticare un Inseguitore della Prateria. Fai pratica con le tue abilità, poi riporta la Bacchetta dell'Addomesticamento a Yaw Chioma Rasa al Villaggio di Zoccolo Sanguinario.",
    [6088] = "Usa la Bacchetta dell'Addomesticamento per addomesticare un Avvoltoio. Fai pratica con le tue abilità, poi riporta la Bacchetta dell'Addomesticamento a Yaw Chioma Rasa al Villaggio di Zoccolo Sanguinario.",
    [6089] = "Parla con Holt Thunderhorn sull'Altura dei Cacciatori di Picco del Tuono.",
    [6101] = "Usa la Bacchetta dell'Addomesticamento per addomesticare una Fiera della Notte Inseguitrice. Fai pratica con le tue abilità, poi riporta la Bacchetta dell'Addomesticamento a Dazalar a Dolanaar.",
    [6102] = "Usa la Bacchetta dell'Addomesticamento per addomesticare uno Stridente Strigide. Fai pratica con le tue abilità, poi riporta la Bacchetta dell'Addomesticamento a Dazalar a Dolanaar.",
    [6103] = "Parla con Jocaste nell'Enclave Cenariana, a Darnassus.",
    [6121] = "Recati a Radaluna e parla con Dendrite Ardistella nel villaggio di Nottequieta.",
    [6122] = "Usa il Campionatore vuoto delle Cascate di Altafonte per prelevare un campione d'acqua dall'imboccatura della grotta presso le cascate.$B$BConsegna il Campionatore pieno delle Cascate di Altafonte ad Alanndarian Cantanotte ad Auberdine, Rivafosca.",
    [6123] = "Porta 5 Radici Terrestri e 12 Funghi Lunari ad Alanndarian Cantanotte ad Auberdine, così che possa preparare un unguento curativo.",
    [6124] = "Usa l'Unguento Curativo per Animali su 10 Caprioli Malaticci sparsi per Rivafosca: dovrebbe curarli. I Caprioli Malaticci sono stati avvistati a partire da sud del Fiume Altafonte, a nord di Auberdine, fino alla parte meridionale di Rivafosca, dove inizia il confine di Valtetra.",
    [6125] = "Torna da Mathrengyl Domaorsi nell'Enclave Cenariana, Darnassus.",
    [6126] = "Recati a Radaluna e parla con Dendrite Ardistella nel villaggio di Nottequieta.",
    [6127] = "Usa il Campionatore vuoto del Picco di Brumafunesta per prelevare un campione d'acqua da una pozza in cima al picco.$B$BConsegna il Campionatore pieno del Picco di Brumafunesta a Tonga Totem Runico al Crocevia, Savane.",
    [6128] = "Porta 5 Radici Terrestri e 5 Corna di Kodo a Tonga Totem Runico al Crocevia, così che possa preparare un unguento curativo.",
    [6129] = "Usa l'Unguento Curativo per Animali su 10 Gazzelle Malaticce sparse nella parte settentrionale delle Savane: dovrebbe curarle. Le Gazzelle Malaticce sono state avvistate a nord della strada est-ovest che attraversa il Crocevia.",
    [6130] = "Torna da Turak Totem Runico all'Altura degli Anziani, a Picco del Tuono.",
    [6141] = "Parla con Fratello Anton a Desolanda.",
    [6144] = "Recati a Sepulcra e parla con Varimathras.",
    [6145] = "Torna nelle Terre Infette Orientali e trova il Corriere Cremisi. Uccidi il corriere e recupera l'Ordine del Gran Crociato.$B$BPorta l'ordine a Nathanos Selvamorta per ulteriori istruzioni.",
    [6146] = "Recati a Mano di Tyr, a sud-est della Cascina dei Marris. Una volta lì, dai un morso alla Mela marcia. Sotto le sembianze della Crociata Scarlatta, consegna l'Ordine del Gran Crociato al Signore dei Crociati Valdelmar.",
    [6147] = "Torna da Nathanos Selvamorta con le nuove informazioni.\\n",
    [6148] = "La Crociata Scarlatta è in movimento. Lungo la strada tra Mano di Tyr e Stratholme troverai l'Oracolo, Demetria, e il suo seguito. Dalle la caccia e uccidila. Se ci riesci, torna da Nathanos Selvamorta.",
    [6163] = "Recati a Stratholme e uccidi Ramstein il Bramacarne. Prendi la sua testa come souvenir per Nathanos.",
    [6402] = "Recati a Roccavento e raggiungi le porte della città. Parla con lo Scudiero Rowe, così che possa informare il Maresciallo Windsor del tuo arrivo.",
    [6403] = "Segui Reginald Windsor attraverso Roccavento. Proteggilo da ogni pericolo!\\n\\nParla con lo Scudiero Rowe se devi contattare di nuovo Reginald Windsor.",
    [6501] = "Devi cercare in tutto il mondo un essere in grado di ripristinare il potere del Frammento dell'occhio del drago. L'unica cosa che sai di tale essere è che esiste.",
    [6502] = "Devi recuperare il sangue del campione dei draghi neri dal Generale Drakkisath.\\n\\nDrakkisath si trova nella sua sala del trono, dietro le Sale dell'Ascensione nei Bastioni di Roccianera.",
    [6566] = "Ascolta Thrall.",
    [6567] = "Trova Rexxar. Il Capoguerra ti ha indicato dove si trova. Cerca lungo i sentieri di Desolanda, tra le Vette di Petrartiglio e Feralas.\\n",
    [6568] = "Consegna il testamento di Rexxar a Myranda la Strega nelle Terre Infette Occidentali.",
    [6569] = "Recati ai Bastioni di Roccianera e raccogli 20 Occhi di dragonide nero. Torna da Myranda la Strega quando hai finito.",
    [6570] = "Recati al Brago dei Dragoni ad Acquemorte e cerca la Tana di Braceardente. Una volta dentro, indossa l'Amuleto della sovversione draconica e parla con Braceardente.\\n",
    [6582] = "Devi trovare Scryer, il campione dei draghi dello Stormo Blu, e ucciderlo. Strappa il teschio dal suo cadavere e portalo a Braceardente.$B$BSai che Scryer si trova a Fontefredda.",
    [6583] = "Distruggi Somnus, il campione dei draghi dello Stormo Verde. Prendi il suo teschio e portalo a Braceardente.",
    [6584] = "A guardia delle Caverne del Tempo, nel Deserto di Tanaris, c'è Chronalis, figlio di Nozdormu. Distruggilo e porta il suo teschio a Braceardente.",
    [6585] = "Recati a Grim Batol e trova Axtroz, il campione dei draghi dello Stormo Rosso. Distruggilo e prendi il suo teschio. Porta il teschio a Braceardente.",
    [6601] = "A quanto pare, la messinscena è finita. Sai che l'Amuleto della sovversione draconica creato per te da Myranda la Strega non funzionerà all'interno dei Bastioni di Roccianera. Forse dovresti trovare Rexxar e spiegargli la situazione. Mostragli l'Amuleto di Fuocodrago opaco. Con un po' di fortuna saprà cosa fare.",
    [6602] = "Recati ai Bastioni di Roccianera e uccidi il Generale Drakkisath. Raccogli il suo sangue e portalo a Rexxar.",
    [6681] = "Porta il Sigillo di Corvolesto a Fahrad al Maniero dei Corvolesto, nascosto tra le colline di Colletorto.$B$BLa tua astuzia sarà messa alla prova lungo il cammino. Preparati.",
    [6721] = "Parla con Dazalar a Dolanaar.",
    [6722] = "Parla con Dazalar a Dolanaar.",
    [6981] = "Recati a Porto Paranco e trova qualcuno che possa dirti di più sulla scheggia brillante.$B$BPoi consegna la scheggia come ti verrà indicato.",
    [7028] = "Raccogli 25 Intagli di cristallo theradrico per Salicino a Desolanda.",
    [7029] = "Riempi la Fiala cerulea rivestita alla pozza di cristallo arancione a Maraudon.$B$BUsa la Fiala cerulea piena sui Viticci Vilstelo per far emergere il Rampollo Nocivo corrotto.$B$BCura 8 piante uccidendo questi Rampolli Nocivi, poi torna da Vark Sfregio Fondo a Predombra.",
    [7041] = "Riempi la Fiala cerulea rivestita alla pozza di cristallo arancione a Maraudon.$B$BUsa la Fiala cerulea piena sui Viticci Vilstelo per far emergere il Rampollo Nocivo corrotto.$B$BCura 8 piante uccidendo questi Rampolli Nocivi, poi torna da Talendria al Presidio di Nijel.",
    [7044] = "Recupera le due parti dello scettro di Celebras: la Verga celebriana e il Diamante celebriano.$B$BTrova un modo per parlare con Celebras.",
    [7046] = "Assisti Celebras il Redento mentre crea lo scettro di Celebras.$B$BParla con lui al termine del rituale.",
    [7064] = "Uccidi la Principessa Theradras e torna da Selendra vicino a Predombra, a Desolanda.",
    [7065] = "Uccidi la Principessa Theradras e torna dal Protettore Marandis al Presidio di Nijel, a Desolanda.",
    [7066] = "Trova Remulos a Radaluna e consegnagli il seme della vita.",
    [7067] = "Leggi le istruzioni dell'emarginato. Poi ottieni l'Amuleto dell'unione a Maraudon e portalo al Centauro Emarginato nella Desolanda meridionale.",
    [7068] = "Raccogli 10 Frammenti di scheggia d'ombra a Maraudon e portali a Uthel'nay a Orgrimmar.",
    [7070] = "Raccogli 10 Frammenti di scheggia d'ombra a Maraudon e portali all'Arcimago Tervosh a Theramore, sulla costa di Acquemorte.",
    [7201] = "Recati ai Sotterranei di Roccianera e recupera 10 Essenze degli Elementi. Il tuo primo istinto è cercare tra i golem e i loro costruttori. Ricordi anche che Vivian Lagrave borbottava qualcosa sugli elementali.",
    [7441] = "Recati a Maglio Infausto e trova l'imp Pusillin. Convinci Pusillin a darti il Libro degli Incantesimi di Azj'tordin con ogni mezzo necessario.$B$BSe riesci a recuperare il Libro degli Incantesimi, torna da Azj'tordin al Padiglione di Lariss, a Feralas.",
    [7461] = "Devi distruggere i guardiani che circondano i 5 Piloni che alimentano la Prigione di Immol'thar. Una volta disattivati i Piloni, il campo di forza che circonda Immol'thar si dissolverà.$B$BEntra nella Prigione di Immol'thar ed elimina l'immondo demone che si trova al suo centro. Infine, affronta il Principe Tortheldrin nell'Ateneo.$B$BSe porterai a termine questa missione, torna dall'Antica Shen'dralar nel cortile.",
    [7462] = "Torna all'Ateneo e trova il Tesoro degli Shen'dralar. Reclama la tua ricompensa!",
    [7463] = "Recati al Quartiere di Legnotorto di Maglio Infausto e uccidi l'Elementale dell'Acqua Hydrospawn. Torna dallo Storico Lydros nell'Ateneo con l'Essenza di Hydrospawn.",
    [7481] = "Cerca Telmius Dreamseeker a Maglio Infausto. Riferisci al Saggio Korolusk all'Accampamento Mojache qualsiasi informazione tu riesca a trovare.",
    [7482] = "Cerca Telmius Dreamseeker a Maglio Infausto. Riferisci alla Studiosa Runaspina a Piumaluna qualsiasi informazione tu riesca a trovare.",
    [7488] = "Porta la Ragnatela di Lethtendris a Latronicus Lanciargentea alla Roccaforte di Piumaluna, a Feralas.",
    [7489] = "Porta la Ragnatela di Lethtendris a Talo Zoccolo Spinoso all'Accampamento Mojache, a Feralas.",
    [7490] = "Porta la Testa di Onyxia a Thrall a Orgrimmar.",
    [7491] = "Cerca il Supremo Natoj nella Valle della Forza.",
    [7492] = "Parla con Talo Zoccolo Spinoso all'Accampamento Mojache, a Feralas.",
    [7493] = "$GUno sterminatore:Una sterminatrice; di draghi e $Gun conciatore esperto:una conciatrice esperta;? Non smetti mai di stupirmi, $Geroe:eroina;. Mi sento onorato.$B$BTi prego, accetta ciò che sto per insegnarti. Questa conoscenza si rivelerà preziosissima se intendi distruggere ciò che resta dello Stormo Nero.$B$BCrea il mantello con le scaglie della madre della covata. Proteggerà te e i tuoi alleati dal soffio incendiario del Signore di Roccianera... Nefarian.",
    [7494] = "Parla con Latronicus Lanciargentea alla Roccaforte di Piumaluna, a Feralas.",
    [7495] = "Porta la Testa di Onyxia al Gran Signore Bolvar Domadraghi a Roccavento.",
    [7496] = "Cerca il Maggiore Mattingly nella Valle degli Eroi.",
    [7497] = "$GUno sterminatore:Una sterminatrice; di draghi e $Gun conciatore esperto:una conciatrice esperta;? Non smetti mai di stupirmi, $Geroe:eroina;. Mi sento onorato.$B$BTi prego, accetta ciò che sto per insegnarti. Questa conoscenza si rivelerà preziosissima se intendi distruggere ciò che resta dello Stormo Nero.$B$BCrea il mantello con le scaglie della madre della covata. Proteggerà te e i tuoi alleati dal soffio incendiario del Signore di Roccianera... Nefarian.",
    [7498] = "Restituisci il libro ai legittimi proprietari.",
    [7499] = "Restituisci il libro ai legittimi proprietari.",
    [7500] = "Restituisci il libro ai legittimi proprietari.",
    [7501] = "Restituisci il libro ai legittimi proprietari.",
    [7502] = "Restituisci il libro ai legittimi proprietari.",
    [7503] = "Restituisci il libro ai legittimi proprietari.",
    [7504] = "Restituisci il libro ai legittimi proprietari.",
    [7505] = "Restituisci il libro ai legittimi proprietari.",
    [7506] = "Restituisci il libro ai legittimi proprietari.",
    [7507] = "Restituisci il Compendio di Nostro sull'Uccisione dei Draghi all'Ateneo.",
    [7508] = "Consegna la Lama Elfica Piatta e Spuntata allo Storico Lydros.",
    [7509] = "Devi fare in modo che Onyxia soffi il suo fuoco sull'Antica Lama Cruda. Fatto questo, raccogli la lama, che ora sarà diventata una Lama Temprata Antica. Ma attenzione: la Lama Temprata Antica non resterà rovente per sempre, quindi il tempo è prezioso.$B$BL'ultimo passo prima di tornare da me è uccidere la bestia e conficcare la Lama Temprata Antica nel suo cadavere.$B$BFallo e Quel'Serrar sarà tua.",
    [7562] = "Parla con Mor'zul Portasangue nelle Steppe Ardenti.",
    [7563] = "Porta 30 bottiglie di Sangue di bestia furiosa a Mor'zul Portasangue nelle Steppe Ardenti.",
    [7564] = "Porta la Cassa di sangue a Gorzeeki Malalente nelle Steppe Ardenti.",
    [7604] = "Se vuoi ricevere il progetto per Sulfuron, riconsegna il Contratto con la Fratellanza del Torio a Lokhtos Pattoscuro.",
    [7623] = "Acquista delle Pozioni d'ombra da Gorzeeki nelle Steppe Ardenti.$B$BUsa le pozioni per attraversare Jaedenar e parla con Sire Banehollow.",
    [7624] = "Affronta Ulathek, poi porta il Cuore del traditore a Sire Banehollow a Jaedenar.",
    [7625] = "Acquista la Polvere di stelle di Xoroth da Ur'dan. Portala a Gorzeeki Malalente nelle Steppe Ardenti.",
    [7626] = "Porta 10 Elisir del potere dell'ombra a Gorzeeki Malalente nelle Steppe Ardenti.",
    [7627] = "Porta 6 Grandi frammenti brillanti e 25 Minerali di ferroscuro a Gorzeeki nelle Steppe Ardenti.",
    [7628] = "Porta 35 Scaglie di drago nero a Gorzeeki Malalente nelle Steppe Ardenti.",
    [7629] = "Porta il Folletto nel barattolo al laboratorio alchemico della Scholomance. Dopo aver creato la pergamena, riporta il barattolo a Gorzeeki Malalente.",
    [7630] = "Porta 3 Barre di arcanite a Gorzeeki nelle Steppe Ardenti.",
    [7631] = "Leggi le istruzioni di Mor'zul. Evoca un Destriero del Terrore di Xoroth, sconfiggilo, poi lega a te il suo spirito.",
    [7632] = "Trova il proprietario dell'Antica foglia pietrificata. Buona fortuna, $n: il mondo è grande.",
    [7634] = "Hastat l'Antico ti ha chiesto di portargli un Tendine di Drago Blu Adulto. Se dovessi trovarlo, riportalo a Hastat a Vilbosco.",
    [7635] = "Stoma l'Antico ti ha chiesto di portargli un Tendine di Drago Nero Adulto. Se dovessi trovarlo, riportalo a Stoma a Vilbosco.",
    [7636] = "Devi trovare e distruggere questi quattro corruttori demoniaci:$B$BMona la Seduttrice.$B$BKlinfran il Pazzo.$B$BSolenor il Sicario.$B$BArtorius l'Araldo della Rovina.$B$BDistruggi queste creature e torna da Vartrus l'Antico a Vilbosco con le loro teste.$B$BConsulta la Corteccia Pietrificata nel tuo inventario per scoprire dove si trovano.$B$BDevi portare a termine questo compito $Gda solo:da sola;.",
    [7637] = "Recati a Forgiardente e ottieni l'Incensiere da esorcismo dell'Alto Sacerdote Rohan. Per ottenerlo dovrai fare una donazione di 150 oro.",
    [7638] = "Parla con Ser Grayson Spezzaombra nel Distretto della Cattedrale di Roccavento.",
    [7639] = "Riporta l'Incensiere da esorcismo a Ser Grayson Spezzaombra nel Distretto della Cattedrale di Roccavento.",
    [7640] = "Usa l'Incensiere da esorcismo per scacciare gli spiriti che tormentano Valterrore. Dopo aver ucciso 25 Spiriti di Valterrore, torna da Ser Grayson Spezzaombra nel Distretto della Cattedrale di Roccavento.",
    [7641] = "Parla con Grimand Elmore nel Distretto dei Nani di Roccavento.",
    [7642] = "Porta 40 Tessuti runici, 6 Barre di arcanite, 10 Lacrime di Arthas, 5 fiale di Acqua santa di Stratholme e 150 oro a Grimand Elmore nel Distretto dei Nani di Roccavento.",
    [7643] = "Procurati lo speciale mangime per nutrire un cavallo spirituale. A quanto pare, è Merideth Carlson a Riva del Sud a fornire questo cibo.$B$BRecati nella spedizione Maglio Infausto, a Feralas, e uccidi Tendris Warpwood. In questo modo libererai l'Antico spirito equino. Dagli lo speciale mangime per calmarlo. Infine, consegnagli la Bardatura di arcanite affinché la benedica.",
    [7644] = "Torna da Ser Grayson Spezzaombra nel Distretto della Cattedrale di Roccavento con la Bardatura di arcanite benedetta.",
    [7645] = "Recupera 20 Biscotti arricchiti di manna, l'ingrediente chiave del Mangime equino arricchito di manna, per Merideth Carlson a Riva del Sud, nelle Alture di Colletorto. L'Alba d'Argento è nota come l'unica fornitrice di questi biscotti.$B$BDevi anche darle 50 oro per placare la sua suscettibilità.",
    [7646] = "Porta un Diamante azerothiano e un Diamante nero immacolato a Ser Grayson Spezzaombra nel Distretto della Cattedrale di Roccavento.",
    [7647] = "Usa lo scrutatore divinatorio nel cuore del seminterrato del Grande Ossario, nella Scholomance. In questo modo appariranno gli spiriti che dovrai giudicare. Sconfiggerli evocherà il Cavaliere della Morte Darkreaver. Sconfiggilo e recupera l'anima perduta del destriero caduto.$B$BConsegna l'Anima redenta del destriero e la Bardatura incantata benedetta al Destriero Caduto di Darkreaver.",
    [7648] = "Porta la Bardatura di arcanite a Ser Grayson Spezzaombra nel Distretto della Cattedrale di Roccavento perché la esamini.",
    [7703] = "Trova il Guanto della Forza Gordok e riportalo al Capitano Kromcrus a Maglio Infausto.$B$BSecondo Kromcrus, la \"storia dei vecchi tempi\" racconta che Tortheldrin, un elfo \"inquietante\" che si faceva chiamare principe, lo rubò a uno dei re Gordok.",
    [7761] = "Che stupido di un Orco! A quanto pare, devi recuperare questo Marchio di Drakkisath per poter usare la Sfera del Comando.$B$BLa lettera indica chiaramente che a custodire il marchio è il Generale Drakkisath. Forse dovresti indagare.",
    [7785] = "Esamina il Contenitore della Rinascita e riportalo al Gran Signore Demitrian.",
    [7786] = "Per liberare Tuonelaar il Vento Eterno dalla sua prigione, devi presentare al Gran Signore Demitrian, a Silitus, la metà destra e la metà sinistra delle Manette del Ventoeterno, 10 lingotti d'Elementio e l'Essenza del Signore del Fuoco.",
    [7787] = "Presenta la Lama Dormiente Benedetta dal Vento al Gran Signore Demitrian.",
    [7877] = "Torna all'Ateneo e trova il Tesoro degli Shen'dralar. Reclama la tua ricompensa!",
    [8181] = "Parla con Yeh'kinya.",
    [8182] = "Parla con Molthor a Rovotorto.",
    [8323] = "L'Eremita Ortell vuole che tu gli porti 10 Testi cifrati del Crepuscolo.",
    [8410] = "Raccogli un campione di aria, fuoco, terra e acqua per Bath'rah il Guardiavento.",
    [8412] = "Porta i pezzi del totem dello spirito a Bath'rah il Guardiavento.",
    [8921] = "Torna da Mux Turbamana a Meccania con 1 Convertitore di arcanite delicato, 4 Essenze eterne superiori, 10 Oli di scagliapietra, 25 Ceneri vulcaniche e 40 oro.",
    [8922] = "Porta il Contenitore di sangue sigillato a Mux Turbamana a Meccania, a Tanaris.",
    [8923] = "Porta il Contenitore di veleno sigillato a Mux Turbamana a Meccania.",
    [8924] = "Usa il distillatore ectoplasmatico vicino ai non morti incorporei per raccogliere 12 Ectoplasmi bruciati a Silitus, 12 Ectoplasmi congelati a Fontefredda e 12 Ectoplasmi stabili nelle Terre Infette Orientali. Portali, insieme al distillatore ectoplasmatico, a Mux Turbamana a Meccania.",
    [8925] = "Trova il Signore del Magma Bokk nelle Steppe Ardenti, ottieni il suo Nucleo di magma e portalo a Mux Turbamana a Meccania.",
    [8928] = "Cerca un folletto in una grotta all'entrata della Gola di Mormoscuro, nella parte meridionale di Fontefredda, acquista una Verga dell'elementale vil e torna da Mux Turbamana a Meccania.",
    [8929] = "Usa il Rivelatore di spettri extradimensionale all'entrata di Stratholme e parla con il fantasma di Anthion Harmon.",
    [8930] = "Usa il Rivelatore di spettri extradimensionale all'entrata di Stratholme e parla con il fantasma di Anthion Harmon.",
    [8945] = "Entra a Stratholme e salva Ysida Harmon dal Barone Rivendare.",
    [8946] = "Porta il Medaglione di Ysida ad Anthion Harmon nelle Terre Infette Orientali.",
    [8947] = "Porta 3 Barre di ferroscuro, 20 Cuoi incantati, 3 Tessuti lunari e 4 Pelli robuste conciate ad Anthion Harmon nelle Terre Infette Orientali.",
    [8948] = "Porta lo Stendardo della provocazione incompleto a Falrin Formaselva nella biblioteca di Maglio Infausto.",
    [8949] = "Raccogli 25 Perline da guerra degli ogre dagli ogre di Maglio Infausto o dei Bastioni di Roccianera e torna da Falrin Formaselva nell'Ateneo di Maglio Infausto.",
    [8950] = "Porta i seguenti oggetti a Falrin Formaselva a Maglio Infausto: 1 Essenza di spettro beffardo, 4 Rune oscure e 8 Grandi frammenti brillanti.",
    [8960] = "Recati al Massiccio Roccianera e usa il Rivelatore di spettri extradimensionale per trovare Bodley vicino ai Bastioni di Roccianera.",
    [8961] = "Raccogli l'Incendicite di Incendius, la Brace di Emberseer e la Cenere di Asharell, insieme a un Braciere consacrato, e portali a Bodley nel Massiccio Roccianera.",
    [8962] = "Ottieni dei Resti druidici e portali a Bodley nel Massiccio Roccianera.",
    [8963] = "Ottieni una Reliquia di Brezzastella e portala a Bodley nel Massiccio Roccianera.",
    [8964] = "Recupera una Spada brillante dello zelo e portala a Bodley nel Massiccio Roccianera.",
    [8965] = "Ottieni le Ceneri d'anima degli esiliati e portale a Bodley nel Massiccio Roccianera.",
    [8966] = "Usa il Braciere del richiamo per evocare lo spirito di Mor Grayhoof e uccidilo. Torna da Bodley nel Massiccio Roccianera con il Frammento sinistro dell'amuleto di Sire Valthalak e il Braciere del richiamo.",
    [8967] = "Usa il Braciere del richiamo per evocare lo spirito di Isalien e uccidila. Torna da Bodley nel Massiccio Roccianera con il Frammento sinistro dell'amuleto di Sire Valthalak e il Braciere del richiamo.",
    [8968] = "Usa il Braciere del richiamo per evocare Jarien e Sothos e uccidili. Torna da Bodley nel Massiccio Roccianera con il Frammento sinistro dell'amuleto di Sire Valthalak e il Braciere del richiamo.",
    [8969] = "Usa il Braciere del richiamo per evocare lo spirito di Kormok e uccidilo. Torna da Bodley nel Massiccio Roccianera con il Frammento sinistro dell'amuleto di Sire Valthalak e il Braciere del richiamo.",
    [8970] = "Raccogli 20 Alghe sanguigne dai naga Strashaz, poi torna da Bodley nel Massiccio Roccianera.",
    [8977] = "Porta il Rivelatore di spettri extradimensionale a Deliana a Forgiardente.",
    [8978] = "Torna da Mokvar a Orgrimmar con il Rivelatore di spettri extradimensionale.",
    [8985] = "Ottieni una Reliquia di Brezzastella e portala a Bodley nel Massiccio Roccianera.",
    [8986] = "Ottieni dei Resti druidici e portali a Bodley nel Massiccio Roccianera.",
    [8987] = "Recupera una Spada brillante dello zelo e portala a Bodley nel Massiccio Roccianera.",
    [8988] = "Ottieni le Ceneri d'anima degli esiliati e portale a Bodley nel Massiccio Roccianera.",
    [8989] = "Usa il Braciere del richiamo per evocare lo spirito di Mor Grayhoof e uccidilo. Torna da Bodley nel Massiccio Roccianera con l'Amuleto di Sire Valthalak ricomposto e il Braciere del richiamo.",
    [8990] = "Usa il Braciere del richiamo per evocare lo spirito di Isalien e uccidila. Torna da Bodley nel Massiccio Roccianera con l'Amuleto di Sire Valthalak ricomposto e il Braciere del richiamo.",
    [8991] = "Usa il Braciere del richiamo per evocare Jarien e Sothos e uccidili. Torna da Bodley nel Massiccio Roccianera con l'Amuleto di Sire Valthalak ricomposto e il Braciere del richiamo.",
    [8992] = "Usa il Braciere del richiamo per evocare lo spirito di Kormok e uccidilo. Torna da Bodley nel Massiccio Roccianera con l'Amuleto di Sire Valthalak ricomposto e il Braciere del richiamo.",
    [8994] = "Raccogli 40 Bracciali di Roccianera e ottieni una Fiasca di potere supremo. Portali a Bodley nel Massiccio Roccianera.",
    [8995] = "Usa il Braciere del richiamo per evocare Sire Valthalak. Eliminalo e usa l'Amuleto di Sire Valthalak sul suo cadavere. Poi riporta l'Amuleto di Sire Valthalak allo Spirito di Sire Valthalak.",
    [8996] = "Torna da Bodley nel Massiccio Roccianera e consegnagli il Braciere del richiamo.",
    [8997] = "Parla con Deliana al Trono Supremo di Forgiardente.",
    [9015] = "Recati all'Anello della Legge nei Sotterranei di Roccianera e pianta lo Stendardo della provocazione al centro mentre l'Alto Giudice Grimstone pronuncia la tua sentenza. Uccidi Theldren e i suoi gladiatori e torna da Anthion Harmon nelle Terre Infette Orientali con il primo pezzo dell'amuleto di Sire Valthalak.",
    [9362] = "Recupera la Conchiglia prismatica per l'Arcimago Xylem. L'Arcimago risiede in una torre in cima alle scogliere di Azshara.",
    [9364] = "Usa Metamorfosi sui naga Spitelash di Azshara e uccidi i cloni che appaiono alcuni secondi dopo. Dopo aver ucciso 50 Cloni Metamorfizzati, torna dall'Arcimago Xylem ad Azshara.",
    [78261] = "Trova il Corno di Xelthos all'interno del Forte di Zannascura. Poi riportalo al punto di consegna segreto di C, vicino al Villaggio di Pirolegno. Devi portare a termine il lavoro $Gda solo:da sola;.",
    [78676] = "Trova l'Occhio di Bhossca all'interno del Monastero Scarlatto. Poi riportalo al punto di consegna segreto di C, vicino al Villaggio di Pirolegno. Devi portare a termine il lavoro $Gda solo:da sola;.",
    [79007] = "I resti carbonizzati della nota sono la tua unica guida.",
    [79008] = "I resti carbonizzati della nota sono la tua unica guida.",
    [79192] = "Stacchi la nota dall'asse e leggi le parole scarabocchiate.",
    [79229] = "Trova qualcuno a Desolanda che sappia qualcosa dell'accampamento saccheggiato.",
    [79235] = "Trova uno dei predoni di Desolanda.",
    [79236] = "Porta un Grog alla Ciliegia a Tokal, a Baia del Bottino, per sentire il resto della sua storia.",
    [79242] = "Trova Illari Duskfeather sulla costa degli Altopiani d'Arathi e accedi al suo nascondiglio di bottino rubato.",
    [79358] = "Raccogli 5 Totem del fuoco distorti, 5 Totem della terra distorti, 5 Totem dell'aria distorti e 5 Totem dell'acqua distorti per Veyric Thunderhame negli Altopiani d'Arathi.",
    [79362] = "Trova la Mazza di Grant su uno degli scheletri nel Cimitero di Collecorvo, poi torna da Sirra Von'indi a Borgoscuro per avere altre informazioni.",
    [79363] = "Sconfiggi 7 Lame Notturne Defias e 7 Incantatori Defias alla Cascina degli Addle, poi torna da Sirra Von'indi a Borgoscuro per avere altre informazioni.",
    [79974] = "Spolverando una borsa da messaggero che spunta dal terreno, trovi una pergamena nascosta tra le provviste.",
    [79975] = "Gli spruzzi d'acqua inumidiscono l'aria, la vista è incredibile.",
    [79976] = "Chiunque fosse qui, se n'è appena andato.",
    [79980] = "Scopri cosa ti attende.",
    [80411] = "Trova il Talismano di Kazdor all'interno di Zul'farrak. Poi portalo a Fahrad al Maniero dei Corvolesto. Devi portare a termine il lavoro $Gda solo:da sola;.",
    [80453] = "Porta il Talismano di Kazdor a Zan Stranavite, nel sotterraneo del Maniero dei Corvolesto.",
    [80454] = "Porta il Talismano Modificato al punto di consegna segreto di Caius, vicino al Villaggio di Pirolegno.",
    [80455] = "Torna da Fahrad al Maniero dei Corvolesto.",
    [80526] = "Parla con Fahrad quando sei pronto ad ascoltare il suo piano.",
