    [86746] = "Uccidi $1oa Satiri Legashi, $2oa Furfanti Legashi e $3oa Richiamainferi Legashi per Ekkal alle Rovine di Eldarth.",
    [86752] = "Parla con il Guardiano del Cancello Rageroar a Ursolan.",
    [86777] = "Uccidi il Maestro Feardred e porta il suo amuleto a Korsa.",
    [86791] = "Trova il gruppo d'esplorazione Blackmaw vicino agli accampamenti Legashi a est di Ursolan.",
    [86792] = "Uccidi $1oa Scatenainferi Legashi, $2oa Rubanime Legashi e $3oa Guardie Nere Legashi per Korsa fuori dalla Roccaforte Legashi.",
