    [86813] = "Somministra la Panacea di Bramblesnap a Furze.",
    [86814] = "Pianta lo Stendardo da guerra dei Mordilegno nella Roccaforte Legashi ad Azshara. Uccidi il Principe Halanox e riferisci la tua vittoria al Guardiano del Cancello Rageroar a Ursolan.",
