    [88821] = "Trova la donna kaldorei vista per l'ultima volta sulla Costa Infranta.",
    [88857] = "Aiuta Keldara Sunblade a fuggire dall'Accampamento di Haldarr, poi parla con il Comandante Truesong al Bivacco di Talrendis.",
