    [89038] = "Cerca il Marchio della Regina tra le rovine del Colosso di Crinocorvo e portalo a Saria Fairmoon ad Azshara.",
    [89053] = "Guarda cosa Saria vuole mostrarti.",
    [89470] = "Riporta lo Zaino di Saria al Comandante Truesong al Bivacco di Talrendis.",
    [90487] = "Viaggia verso ovest dalla grotta dell'eremita per trovare un avamposto di antichi e driadi sulle pendici inferiori del Monte Hyjal.",
