    [96369] = "Torna dal Comandante Folkar.",
    [96376] = "<Ti viene in mente che Nazgrel, in quanto consigliere del Capoguerra, potrebbe essere molto interessato ai documenti che hai recuperato nelle Marche Occidentali. Chiedigli se questi documenti hanno un senso per lui.>",
    [96377] = "<Ti viene in mente che il goblin braccio destro di Shaw potrebbe essere interessato ai documenti che hai recuperato nelle Marche Occidentali. Chiedigli se questi documenti hanno un senso per lui.>",
    [96379] = "<Ti viene in mente che un goblin che si occupa di recupero beni potrebbe essere molto interessato ai documenti che hai recuperato nelle Marche Occidentali. Chiedigli se questi documenti hanno un senso per lui... e, soprattutto, quanto sarebbe disposto a pagarti per averli.>",
    [96381] = "Entra nella Prigione di Alcaz, uccidi 15 Soldati Strashaz e 8 Incantatrici Strashaz, e porta la testa della Signora delle Maree Ca'zass a Sully McCleary.",
    [96435] = "Getta le ossa degli stregoni sul mucchio di ossa vicino alle pozze di melma.",
    [96770] = "Uccidi il Taumaturgo Zum'rah e porta la Testa di Zum'rah all'Arcimago Lan'dalock a Dalaran.",
    [96771] = "Recati alla Roccaforte di Krol'dok e uccidi Zalfan Moonshadow.",
    [96772] = "Recupera il Diario di Zarla dalle profondità della Prigione di Alcaz.",
    [96774] = "Recupera un Antico Idolo dei Gurubashi dalla Città Sommersa.",
    [96775] = "Uccidi il Taumaturgo Zum'rah e porta la Testa di Zum'rah a Mazu'kon a Mulgore.",
    [96776] = "Recupera da Maraudon il cristallo noto come Splendore di An'she.",
    [96779] = "Trova Lord Tomas all'interno del Forte Durnholde, nelle Alture di Colletorto, e uccidilo. Poi torna da Myrokos Silente.",
    [96781] = "Ruba il Rapporto di Ricognizione di Barton borseggiandolo. Poi porta il rapporto a Myrokos Silente al Maniero dei Corvolesto.",
    [96782] = "Trova la Lama del Casato Perenolde e l'Egida Reale di Perenolde tra le Rovine d'Alterac. Poi portale a Myrokos Silente.",
    [96783] = "Ruba un'uniforme della Lega dei Tagliagole dal Maniero dei Norten per infiltrarti nel Forte di Stromgarde.",
    [96784] = "Sotto le mentite spoglie di un membro della Lega dei Tagliagole, trova qualcuno nel Forte di Stromgarde che sappia dell'accordo segreto.",
    [96785] = "Trova qualcosa nel Forte di Stromgarde per convincere Anastasia a rivelare i dettagli dell'accordo segreto.",
    [96786] = "Manda a monte l'accordo segreto e prendi l'oggetto che viene ceduto alla Lega dei Tagliagole. Poi torna da Myrokos Silente al Maniero dei Corvolesto.",
    [96800] = "Recupera il libro La magia perduta dei Maestri delle Rune dal Monastero Scarlatto.",
    [96930] = "Torna dalla Cornacchia Curiosa.",
    [96931] = "Tocca l'Effigie del Corvo sul ponte che domina la Culla della Tranquillità per richiamare la divinità selvaggia Jereman.",
    [96939] = "Parla con la divinità selvaggia Marrosis.",
    [96964] = "Parla con la divinità selvaggia Renalard.",
    [97022] = "Parla con Danitha Morr al Forte Bandarion.",
    [97130] = "Recupera un Antico Idolo dei Gurubashi dalla Città Sommersa.",
    [97168] = "Se vuoi aiutare Eldrun Stormbreaker a Forgiardente, portagli un Diamante Azerothiano e un Diamante Nero Perfetto.",
    [97169] = "Usa lo scrutatore divinatorio nel cuore del seminterrato del Grande Ossario, a Scholomance. Così facendo, farai apparire degli spiriti che dovrai combattere. Sconfiggere questi spiriti evocherà il Cavaliere della Morte Darkreaver: sconfiggilo.$B$BPorta la Testa di Darkreaver a Eldrun Stormbreaker nelle Caverne Desolate, a Forgiardente.",
    [97173] = "Recupera un Totem Rituale degli Zannanera dalla Tana degli Zannanera.",
    [97174] = "Parla con Danitha Morr al Forte Bandarion, nelle Radure di Tirisfal.",
    [97175] = "Recati a Orgrimmar e procurati il Turibolo dell'Esorcismo del Sommo Sacerdote Zayus. Per ottenerlo dovrai fare una donazione di 150 monete d'oro.",
    [97176] = "Usa il Turibolo dell'Esorcismo per scacciare gli spiriti tormentati di Valterrore. Dopo aver distrutto 25 Spiriti di Valterrore, torna da Danitha Morr al Forte Bandarion, nelle Radure di Tirisfal.",
    [97177] = "Restituisci il Turibolo dell'Esorcismo a Danitha Morr al Forte Bandarion, nelle Radure di Tirisfal.",
    [97178] = "Parla con Nov nel villaggio di Mulino di Tarren, nelle Alture di Colletorto.",
    [97179] = "Porta 40 Pezze di Stoffa Runica, 6 Barre d'Arcanite, 10 Lacrime di Arthas, 5 fiale di Acqua Santa di Stratholme e 150 monete d'oro a Nov nelle Alture di Colletorto.",
    [97180] = "Porta la Bardatura di arcanite a Danitha Morr al Forte Bandarion per un'ispezione.",
    [97182] = "Procurati del mangime speciale per nutrire un cavallo spirituale. Nathanos Selvamorta, nelle Terre Infette Orientali, potrebbe essere in grado di fornirtelo.$B$BRecati a Maglio Infausto, a Feralas, e uccidi Tendris Warpwood. Così libererai l'Antico Spirito Equino. Nutrilo con il mangime speciale per calmarlo.$B$BInfine, consegnagli la Bardatura di Arcanite e spera che sia disposto a concederti la sua benedizione.",
    [97183] = "Torna da Danitha Morr al Forte Bandarion, nelle Radure di Tirisfal, con la Bardatura di arcanite benedetta.",
    [97184] = "Porta un Diamante Azerothiano e un Diamante Nero Perfetto a Danitha Morr al Forte Bandarion, nelle Radure di Tirisfal.",
    [97185] = "Usa lo scrutatore divinatorio nel cuore del seminterrato del Grande Ossario, a Scholomance. Così facendo, farai apparire gli spiriti che dovrai giudicare. Sconfiggere questi spiriti evocherà il Cavaliere della Morte Darkreaver. Sconfiggilo e recupera l'anima perduta del destriero caduto.$B$BConsegna lo Spirito della Punizione e la Bardatura Incantata Benedetta al Destriero Caduto di Darkreaver.",
    [97186] = "Procura 20 Biscotti di Manna Arricchiti per Nathanos Selvamorta nelle Terre Infette Orientali. L'Alba d'Argento è nota per essere l'unica a fornire questi biscotti. Dovrai anche consegnare a Selvamorta 50 monete d'oro per il suo disturbo.",
    [97197] = "Recupera un Frammento delle Terre del Fuoco dai Sotterranei di Roccianera per Alaana Stormwalker a Mulgore.",
    [97198] = "Recupera un Totem Rituale degli Zannanera dalla Tana degli Zannanera.",
    [97243] = "Porta la Torcia della Fiamma Dormiente a Olariaan Swiftburn al Santuario delle Fiamme nei Bassopiani di Gustberry.",
    [97244] = "Uccidi il Sacerdote del Cielo Faladiel nei Bassopiani di Gustberry e raccogli il Cuore di Faladiel.",
    [97245] = "Trova la dimora di Kuramaa negli Altopiani di Shen'dar e sconfiggi lo spirito in combattimento. Dopo la vittoria, porta la Maschera di Kuramaa a Olariaan Swiftburn nei Bassopiani di Gustberry.",
    [97250] = "Uccidi i soldati dell'Alleanza che sconfinano nelle Savane al confine con Acquemorte, poi torna dal Grunt Logmar al Campo Taurajo.",
    [97257] = "Aspetta che Olariaan inizi il rituale al Braciere delle Offerte e segui le sue istruzioni. Devi portare la Fiamma Eterna a Valanaar prima che scada il tempo.",
    [97288] = "Consegna la Testa Abominevole al Maestro Speziale Faranell a Sepulcra.",
    [97289] = "Porta la Testa del Barone al corpo di Othmar a Sepulcra.",
    [97290] = "Riferisci le tue scoperte al Maestro Speziale Faranell a Sepulcra.",
    [97291] = "Procurati un Cappuccio Tossico da Tawny Grisette nel Quartiere del Commercio, dell'Erba Vescicante vicino all'istruttore di erbalismo e un'Essenza d'Agonia dal venditore di veleni nel Quartiere dei Ladri per il Maestro Speziale Faranell a Sepulcra.",
    [97292] = "Inietta il Siero Sibilante nel congegno sopra il corpo di Othmar per il Maestro Speziale Faranell.",
    [97327] = "Entra nella Tana degli Zannanera e recupera 5 Borse degli Zannanera per Ekkal alle Rovine di Eldarath, ad Azshara.",
    [97411] = "Procurati 15 Campioni di Veleno di Silitus e 20 monete d'oro e portali, insieme a un paio di Bracciali della Forgia della Luce, a Mokvar a Orgrimmar.",
