    [97447] = "Procurati 15 Campioni di Sangue di Fontefredda e 20 monete d'oro e portali, insieme a un paio di Polsiere degli Elementi, a Deliana a Forgiardente.",
    [97448] = "Porta un Cordone degli Elementi e un paio di Guanti degli Elementi a Deliana a Forgiardente.",
    [97449] = "Torna da Deliana a Forgiardente con un set di Stivali degli Elementi, Kilt degli Elementi e Spallacci degli Elementi.",
