    [98396] = "Recupera la Reliquia della Zanna, la Reliquia dell'Artiglio e la Reliquia dell'Ombra Silente dalla Tana dei Tumuli di Grantempesta e riportale al Grande Spirito Felino.",
    [98397] = "Torna a Darnassus e parla con Mathrengyl Domaorsi nell'Enclave Cenariana.",
    [98404] = "Recupera la Reliquia della Zanna, la Reliquia dell'Artiglio e la Reliquia dell'Ombra Silente dalla Tana dei Tumuli di Grantempesta e riportale all'Avatar di Saeyleenan.",
    [98405] = "Cerca il Grande Spirito Felino nella parte meridionale di Radaluna e scopri cosa ha da insegnarti sulla natura del felino.",
    [98447] = "Scopri la causa dei fantasmi della famiglia Valor a Collecorvo per Sirra Von'indi a Borgoscuro.",
    [98512] = "Uccidi 10 Assassini Al'Aketh negli Altopiani di Shen'dar.",
    [98517] = "Fai rapporto a Sessaria Skystride o ad Aarnor Galestrike sull'Isola di Zephras per proseguire il tuo addestramento da Sciamano.$B$BPuoi tornare a Zephras con il trasporto fendicieli che attracca a Mulgore, presso l'Altopiano di Skywatcher, a nord-ovest di Picco del Tuono.",
